#include "metrics.h"
#include <math.h>
double point_distance(Point2D a,Point2D b){return hypot(a.x-b.x,a.y-b.y);} ErrorStats compute_stats(const double*e,size_t n){ErrorStats s={.count=n};if(!e||!n)return s;double sum=0,ss=0;for(size_t i=0;i<n;i++){sum+=e[i];ss+=e[i]*e[i];if(e[i]>s.max)s.max=e[i];}s.mean=sum/n;s.rmse=sqrt(ss/n);return s;}
ErrorStats gps_error_stats(const SimulationResult*s){ErrorStats z={0};if(!s)return z;double sum=0,ss=0;for(size_t i=0;i<s->gps_count;i++){const GpsMeasurement*g=&s->gps[i];if(!g->valid||g->step>=s->truth_count)continue;double e=point_distance(g->pos,s->truth[g->step].pos);sum+=e;ss+=e*e;if(e>z.max)z.max=e;z.count++;}if(z.count){z.mean=sum/z.count;z.rmse=sqrt(ss/z.count);}return z;}
ErrorStats estimate_error_stats(const SimulationResult*s,const EstimateSample*e,size_t n,int(*keep)(const TruthSample*,void*),void*ctx){ErrorStats z={0};if(!s||!e)return z;double sum=0,ss=0;for(size_t i=0;i<n;i++){if(e[i].step>=s->truth_count)continue;const TruthSample*t=&s->truth[e[i].step];if(keep&&!keep(t,ctx))continue;double d=point_distance(e[i].pos,t->pos);sum+=d;ss+=d*d;if(d>z.max)z.max=d;z.count++;}if(z.count){z.mean=sum/z.count;z.rmse=sqrt(ss/z.count);}return z;}
